#!/usr/bin/env Rscript
# B28 figure suite — cross-study proteomic transfer reliability, ggplot2, Arial.
# Reads current plotdata CSVs (figures/plotdata/).
# Current CSVs are regenerated by export_revision.py from the verified corrected
# 2026-09-22 predictions. Historical snapshot numbers are not current evidence.
#
# Figures:
#   F1  cross-study transfer map: per-cohort abundance vs missingness vs trivial AUROC (A);
#       per-cohort AUROC vs ECE (B) — overconfidence concentrates where transfer is hardest.
#   F2  comparator performance: separate macro/pooled AUROC for missingness, global
#       summaries and accession abundance. No biological partition or old CI whiskers.
#   F3  calibration & the CV-design leak: reliability diagram for honest grouped (LOGO) vs
#       random 5-fold evaluation (A); pooled ECE under each evaluation (B).
#   F4  selective abstention: retained accuracy vs coverage when low-confidence cases are
#       deferred (A); cohort composition of the retained set at each coverage (B).
#   F5  split unit, not patient pairing: per-fold and pooled AUROC (A) and ECE (B) for random
#       5-fold, patient-grouped 5-fold, and LOGO.
#   F6  per-cohort sensitivity of the LOGO result to model family (A) and imputation
#       protocol (B) — the pooled nulls quoted in the text hide per-cohort disagreement.
#   F7  fitted recalibration temperature per held-out cohort against the no-rescaling line.
suppressMessages({ library(ggplot2); library(dplyr); library(tidyr) })
HERE <- tryCatch(dirname(sub("^--file=", "", grep("^--file=", commandArgs(FALSE), value = TRUE))),
                 error = function(e) ".")
if (length(HERE) == 0 || HERE == "") HERE <- "scripts/R"
source(file.path(HERE, "theme_b28.R"))
source(file.path(HERE, "compose_b28.R"))
BASE <- normalizePath(file.path(HERE, "..", ".."))
PD   <- file.path(BASE, "figures", "plotdata")
FIG  <- file.path(BASE, "figures")
rd   <- function(f) read.csv(file.path(PD, f), stringsAsFactors = FALSE, check.names = FALSE)
NUMBERED_ONLY <- identical(Sys.getenv("B28_NUMBERED_ONLY", unset = ""), "1")

# Shared cohort order and palette, easiest to hardest transfer by abundance AUROC
# Current b28_transfer.csv determines the cohort points and corrected ordering.
# Cool hues = cohorts the model transfers to well, warm = the overconfident ones.
COH_EASY_FIRST <- c("LUAD", "LSCC", "HNSCC", "UCEC", "PDAC", "CCRCC")
COHCOL <- c(LUAD = oi("blue"), LSCC = oi("sky"), HNSCC = oi("green"),
            UCEC = oi("orange"), CCRCC = oi("purple"), PDAC = oi("verm"))
# Redundant glyph channel for the cohort variable. Okabe-Ito is colourblind-safe pairwise but
# orange/vermillion (UCEC/PDAC) and blue/sky (LUAD/LSCC) are its closest pairs, and in F4B those
# series also overlap numerically, so hue alone does not separate them. Filled and open glyphs are
# mixed so the panel also survives greyscale.
COHSHP <- c(LUAD = 16, LSCC = 17, HNSCC = 15, UCEC = 18, CCRCC = 1, PDAC = 2)
# Detached-figure disclosure (F2–F7). Same words as F1B / TOC. Do not weaken,
# and do not imply a deconfounded AUROC: the grouping variable is a cancer/study cohort.
BATCH_EQ <- "cancer/study confounded"

# ---------------- F1: cross-study transfer map ----------------
tr <- rd("b28_transfer.csv")
# The pre-existing display trace below belongs only to this frozen input.
# Stop on changed data rather than reuse stale geometry or silently refit it.
if (!identical(unname(tools::md5sum(file.path(PD, "b28_transfer.csv"))),
               "cfcb50385bc2df7f6866d305599e08fd")) {
  stop("Frozen F1 display trace requires unchanged b28_transfer.csv", call. = FALSE)
}
ord <- tr$cohort[order(tr$auc_abundance)]
trl <- tr %>%
  pivot_longer(c(auc_abundance, auc_missingness, auc_trivial),
               names_to = "feat", values_to = "auc") %>%
  mutate(cohort = factor(cohort, ord),
         feat = recode(feat, auc_abundance = "abundance",
                       auc_missingness = "missingness", auc_trivial = "trivial"),
         feat = factor(feat, c("abundance", "trivial", "missingness")))
# Short legend keys: the long forms ("full abundance", "trivial intensity",
# "missingness only") overflowed the top legend after each panel kept its
# own ylab.  The caption still uses the long names.
FCOL <- c("abundance" = oi("blue"), "trivial" = oi("orange"),
          "missingness" = oi("grey"))
pA <- ggplot(trl, aes(cohort, auc, fill = feat)) +
  geom_hline(yintercept = 0.5, linetype = "dashed", linewidth = 0.4, colour = "grey40") +
  geom_col(position = position_dodge(0.78), width = 0.72, alpha = 0.95) +
  scale_fill_manual(values = FCOL) +
  # House case: ALL-CAPS cohort codes match F1B labels / body / Table 1 (PDAC, CCRCC, …).
  scale_x_discrete(labels = function(x) toupper(as.character(x))) +
  scale_y_continuous(limits = c(0, 1.02), expand = expansion(c(0, 0.02))) +
  labs(title = "Leave-one-cohort-out transfer",
       x = "held-out cancer/study cohort",
       y = "leave-one-cohort-out AUROC") +
  theme_b1() + theme(panel.grid.major.x = element_blank(),
                     legend.position = "top", legend.justification = "center",
                     legend.margin = margin(0, 0, 2, 0),
                     legend.text = element_text(size = B28_MIN_TEXT_PT))
# Colour + shape carry the cohort, not on-plot lettering.  Six ggrepel labels
# (plus leader lines) previously buried the six points they named — the
# type-to-data defect on this panel.  The caption still names every cohort.
tr$cohort_lab <- factor(toupper(tr$cohort), levels = COH_EASY_FIRST)
pB <- ggplot(tr, aes(auc_abundance, ece_abundance)) +
  # Frozen display-only trace from the pre-refinement F1 PDF (2026-10-01).
  # Reuse its two vector endpoints; rendering must not perform a fresh lm fit.
  annotate("segment", x = 0.8484882088, xend = 0.9998209843,
           y = 0.2621968285, yend = 0.0102902937,
           linewidth = 0.4, colour = "grey60", linetype = "dashed") +
  geom_point(aes(colour = cohort_lab, shape = cohort_lab), size = 3.4) +
  scale_colour_manual(values = COHCOL) +
  scale_shape_manual(values = COHSHP) +
  # Tight expand: the old 0.11 right pad existed only to park ggrepel labels.
  scale_x_continuous(limits = c(0.74, 1.02), expand = expansion(c(0.03, 0.04))) +
  scale_y_continuous(limits = c(0, 0.32), expand = expansion(c(0.02, 0.04))) +
  # The grouping variable is confounded: naming it on the axis keeps the anti-correlation
  # from reading as a proteomic transfer law.  Wrapped, because b1_save squeezes this panel
  # to ~2.5in and a single-line axis title runs off the device.
  labs(title = "Miscalibration tracks transfer difficulty",
       x = "abundance AUROC\n(cancer and study confounded)",
       y = "expected calibration error") +
  theme_b1() + theme(legend.position = "right",
                     legend.key.height = unit(0.75, "lines"))
f1 <- b28_compose(list(pA, pB), widths = c(1.22, 1.12))
b1_save(f1, "b28_F1_transfer", 13, 5.6, FIG)

# ---------------- F2: distinct comparator estimands ----------------
ld <- rd("b28_ladder.csv")
arm_ord <- ld$arm[order(ld$auc)]
ld$arm <- factor(ld$arm, levels = arm_ord)
ARMCOL <- c("missingness mask only" = oi("grey"),
            "global summaries (3 features)" = oi("orange"),
            "abundance (8906 accessions)" = oi("blue"))
ldl <- ld %>% pivot_longer(c(macro_auc, auc), names_to = "estimand", values_to = "value") %>%
  mutate(estimand = recode(estimand, macro_auc = "Equal-cohort macro", auc = "Cross-model pooled"))
pL <- ggplot(ldl, aes(value, arm, colour = arm, shape = estimand)) +
  geom_vline(xintercept = 0.5, linetype = "dashed", linewidth = 0.4, colour = "grey40") +
  geom_point(size = 3, position = position_dodge(width = 0.45)) +
  scale_colour_manual(values = ARMCOL, guide = "none") +
  scale_shape_manual(values = c("Equal-cohort macro" = 16, "Cross-model pooled" = 2)) +
  scale_x_continuous(limits = c(0.45, 1.0)) +
  labs(title = "Comparator performance is not a biological partition",
       x = paste0("LOGO AUROC (two distinct estimands)\n", BATCH_EQ), y = NULL, shape = NULL) +
  theme_b1() + theme(panel.grid.major.y = element_blank(), legend.position = "top")
b1_save(pL, "b28_F2_signal_ladder", 10, 3.7, FIG)

# ---------------- F3: calibration & CV-design leak ----------------
rel <- rd("b28_reliability.csv") %>%
  mutate(method = factor(method, c("random 5-fold (mixes cohorts)", "LOGO (grouped, honest)")))
ECOL <- c("random 5-fold (mixes cohorts)" = oi("grey"), "LOGO (grouped, honest)" = oi("verm"))
pRel <- ggplot(rel, aes(conf, acc, colour = method)) +
  geom_abline(slope = 1, intercept = 0, linetype = "dashed", linewidth = 0.4, colour = "grey50") +
  geom_line(linewidth = 0.8) + geom_point(size = 1.8) +
  scale_colour_manual(values = ECOL, labels = c("random 5-fold", "LOGO")) +
  scale_x_continuous(limits = c(0, 1)) + scale_y_continuous(limits = c(0, 1)) +
  labs(title = paste0("Random CV hides miscalibration\n(", BATCH_EQ, ")"),
       x = "mean predicted P(tumor)", y = "observed fraction tumor") +
  theme_b1() + theme(legend.position = "top", legend.justification = "center",
                     legend.text = element_text(size = B28_MIN_TEXT_PT))
ec <- rd("b28_ece_compare.csv")
ec$eval <- factor(ec$eval, ec$eval[order(ec$ece)])
pE <- ggplot(ec, aes(eval, ece, fill = eval)) +
  geom_col(width = 0.6, alpha = 0.9) +
  geom_text(aes(label = sprintf("ECE %.3f\nAUROC\n%.3f", ece, auc)), vjust = -0.35,
            size = b28_text_mm(), family = B1_FONT) +
  scale_fill_manual(values = c("Patient CV"=oi("orange"), "Sample CV"=oi("grey"), "LOGO"=oi("verm")), guide = "none") +
  scale_y_continuous(limits = c(0, 0.16), expand = expansion(c(0, 0.18))) +
  # Short ylab: the panel title already says ECE, and the long form was
  # clipped at the cell edge under the previous shared-gutter compositor.
  labs(title = "ECE by evaluation protocol",
       x = paste0("evaluation protocol\n(", BATCH_EQ, ")"), y = "pooled ECE") +
  theme_b1() + theme(panel.grid.major.x = element_blank(),
                     axis.text.x = element_text(size = B28_MIN_TEXT_PT))
f3 <- b28_compose(list(pRel, pE), widths = c(1.12, 1))
b1_save(f3, "b28_F3_calibration", 12, 4.8, FIG)

# ---------------- F4: selective abstention ----------------
rc <- rd("b28_riskcoverage.csv")
full_acc <- rc$full_acc[1]
pRC <- ggplot(rc, aes(coverage, retained_acc_conf)) +
  geom_hline(yintercept = full_acc, linetype = "dashed", linewidth = 0.4, colour = "grey40") +
  # Sit the key in the empty band above the dashed line, not on the rule
  # (the previous +0.006 / vjust=0 parked the glyphs on the ink).
  annotate("text", x = 0.18, y = full_acc + 0.016, hjust = 0, vjust = 0,
           label = sprintf("no abstention (%.3f)", full_acc), size = b28_text_mm(),
           colour = "grey40", family = B1_FONT) +
  geom_line(linewidth = 0.7, colour = oi("blue")) +
  geom_point(size = 1.8, colour = oi("blue")) +
  scale_x_continuous(limits = c(0.05, 1.0)) +
  scale_y_continuous(limits = c(0.83, 1.005), expand = expansion(c(0, 0.01))) +
  labs(title = "Selective abstention\non the honest split",
       x = paste0("coverage\n(fraction of cases predicted)\n(", BATCH_EQ, ")"),
       y = "retained accuracy") +
  theme_b1()

# F4B: what the abstention is actually selecting.  Committed b28_riskcoverage_cohort.csv, the
# same cells Table 2 tabulates; drawing them puts the retained-set cohort mix in the figure the
# Conclusions cites for it. Lines retain small cohort shares without cumulative stacking.
rcc <- rd("b28_riskcoverage_cohort.csv") %>%
  pivot_longer(all_of(c("Ccrcc", "Luad", "Ucec", "Hnscc", "Lscc", "Pdac")),
               names_to = "cohort", values_to = "frac") %>%
  mutate(cohort = factor(toupper(cohort), COH_EASY_FIRST))
pRCC <- ggplot(rcc, aes(coverage, frac, colour = cohort, shape = cohort)) +
  geom_line(linewidth = 0.7) + geom_point(size = 1.9) +
  scale_colour_manual(values = COHCOL) +
  scale_shape_manual(values = COHSHP) +
  scale_x_continuous(limits = c(0.1, 1.0)) +
  scale_y_continuous(limits = c(0, 0.52), expand = expansion(c(0, 0.02))) +
  # At 10% coverage UCEC is absent but PDAC contributes two cases. The caption
  # states this corrected inventory rather than implying both cohorts are absent.
  labs(title = "Retained cohort composition changes with coverage",
       x = paste0("coverage\n(fraction of cases predicted)\n(", BATCH_EQ, ")"),
       y = "share of the retained set") +
  theme_b1() + theme(legend.position = "right",
                     legend.key.height = unit(0.75, "lines"))
f4 <- b28_compose(list(pRC, pRCC), widths = c(1, 1.24))
b1_save(f4, "b28_F4_riskcoverage", 13, 5.4, FIG)

# ---------------- F5: the split unit, not patient pairing ----------------
# Committed b28_protocol_summary.csv carries every individual fold for the two cross-validation
# protocols and every held-out cohort for LOGO; only the four pooled rows had reached the page.
# No interval is drawn: the folds themselves are the replicate set, and no committed cell holds a
# per-protocol bootstrap CI, so inventing whiskers here would be a fabricated statistic.
ps <- rd("b28_protocol_summary.csv")
# Short tick labels only: b1_save squeezes each panel to ~2.6in, and the parenthetical
# descriptors collided across the three categories.  The caption spells all three out.
PROT <- c(random_5fold = "random\n5-fold",
          patient_gkf  = "patient\ngrouped",
          logo_xgb     = "LOGO")
PROTCOL <- setNames(c(oi("grey"), oi("orange"), oi("verm")), unname(PROT))
mk_prot <- function(d) d %>%
  mutate(prot = factor(PROT[protocol], levels = unname(PROT)), xc = as.numeric(prot))
psf <- ps %>% filter(protocol %in% names(PROT), fold_id != "pooled") %>%
  mk_prot() %>% group_by(prot) %>%
  # Deterministic fan-out around the category centre; no jitter, so the build stays byte-stable.
  mutate(x = xc - 0.13 + (row_number() - (n() + 1) / 2) * 0.075) %>% ungroup()
psp <- ps %>% filter(protocol %in% names(PROT), fold_id == "pooled") %>%
  mk_prot() %>% mutate(x = xc + 0.24)
prot_panel <- function(yfold, ypool, ylab, ttl, ylim, fmt, tag) {
  ggplot(psf, aes(x, .data[[yfold]], colour = prot)) +
    geom_point(size = 2.0, alpha = 0.9) +
    geom_point(data = psp, aes(x, .data[[ypool]], colour = prot), shape = 23, size = 3.2,
               stroke = 0.7, fill = "white") +
    geom_text(data = psp, aes(x, .data[[ypool]], colour = prot,
                              label = sprintf(fmt, .data[[ypool]])),
              # Display-only clearance above nearby calibration-fold points.
              nudge_y = if (identical(yfold, "ece")) 0.045 else 0,
              vjust = -1.1, size = b28_text_mm(), family = B1_FONT, show.legend = FALSE) +
    scale_colour_manual(values = PROTCOL, guide = "none") +
    scale_x_continuous(breaks = 1:3, labels = unname(PROT), limits = c(0.55, 3.45)) +
    scale_y_continuous(limits = ylim) +
    labs(title = ttl, x = paste0("evaluation protocol\n(", BATCH_EQ, ")"), y = ylab) +
    theme_b1() + theme(panel.grid.major.x = element_blank(),
                       axis.text.x = element_text(size = B28_MIN_TEXT_PT))
}
# Caption already states filled circle = fold, open diamond = pooled; the
# parenthetical is not repeated on the axis (type-to-data).
f5 <- b28_compose(list(
  prot_panel("auc", "pooled_auc", "AUROC",
             "Discrimination by split unit", c(0.75, 1.03), "%.3f", "A"),
  prot_panel("ece", "pooled_ece", "expected calibration error",
             "Calibration by split unit", c(0, 0.31), "%.3f", "B")
))
b1_save(f5, "b28_F5_protocol", 12, 4.6, FIG)

# ---------------- F6: per-cohort sensitivity of the LOGO result ----------------
# Both arms are quoted in the text only as pooled near-nulls (L2 within 0.002 AUROC of XGBoost;
# leaky imputation within 0.002 of honest).  The committed per-cohort cells show those pools are
# cancellations, not agreement.  Dumbbells show both committed endpoints; no derived delta is
# printed, so nothing on the face is a number I computed.
COHORD <- rev(c("CCRCC", "PDAC", "UCEC", "HNSCC", "LSCC", "LUAD"))  # hardest at the top
dumbbell <- function(d, x1, x2, lab1, lab2, col1, col2, ttl, xlim, tag) {
  d <- d %>% filter(cohort != "pooled") %>%
    mutate(coh = factor(toupper(cohort), COHORD))
  # Shape is a second channel so near-coincident endpoints (easy cohorts on
  # the leaky arm) stay readable as two marks, not one blob.
  ggplot(d, aes(y = coh)) +
    geom_segment(aes(x = .data[[x1]], xend = .data[[x2]], y = coh, yend = coh),
                 linewidth = 0.6, colour = "grey72") +
    geom_point(aes(x = .data[[x1]], colour = lab1, shape = lab1), size = 2.7) +
    geom_point(aes(x = .data[[x2]], colour = lab2, shape = lab2), size = 2.7) +
    scale_colour_manual(values = setNames(c(col1, col2), c(lab1, lab2))) +
    scale_shape_manual(values = setNames(c(16, 2), c(lab1, lab2))) +
    scale_x_continuous(limits = xlim) +
    labs(title = ttl, x = paste0("leave-one-cohort-out AUROC\n(", BATCH_EQ, ")"), y = NULL) +
    theme_b1() + theme(panel.grid.major.y = element_blank(),
                       legend.position = "top", legend.justification = "center",
                       legend.margin = margin(0, 0, 2, 0))
}
# Both panels carry the same quantity and the figure's claim is that the two per-cohort movements
# are of comparable size, so they share one x range.  On separate ranges (A 0.31 wide, B 0.25 wide)
# panel B drew 1.24x longer per unit AUROC and its smaller movements read as equal to A's larger
# ones.  Panel B's smallest datum is 0.794, so the shared range clips nothing.
F6_XLIM <- c(0.71, 1.02)
f6 <- b28_compose(list(
  dumbbell(rd("b28_l2_vs_xgb.csv"), "auc_xgb", "auc_l2",
           "XGBoost", "L2-logistic", oi("blue"), oi("purple"),
           "Model family", F6_XLIM, "A"),
  dumbbell(rd("b28_leaky_compare.csv"), "auc_honest", "auc_leaky",
           "in-fold median", "full-data median", oi("verm"), oi("grey"),
           "Imputation protocol", F6_XLIM, "B")
))
b1_save(f6, "b28_F6_sensitivity", 12, 4.2, FIG)

# ---------------- F7: fitted recalibration temperature ----------------
# The T column of the committed b28_recal_summary.csv appears nowhere else in the paper; it is
# the mechanism behind Table 3's "helps hard cohorts, hurts easy ones".
rs <- rd("b28_recal_summary.csv") %>% filter(cohort != "pooled")
rs <- rs %>% mutate(coh = factor(toupper(cohort), toupper(cohort[order(auc)])),
                    axlab = sprintf("%s\nECE %.3f", toupper(cohort), ece_before))
pT <- ggplot(rs, aes(coh, T)) +
  geom_hline(yintercept = 1, linetype = "dashed", linewidth = 0.4, colour = "grey40") +
  geom_segment(aes(xend = coh, y = 1, yend = T), linewidth = 0.5, colour = "grey75") +
  geom_point(size = 3.2, colour = oi("blue")) +
  geom_text(aes(label = sprintf("%.3f", T)), vjust = -0.9, size = b28_text_mm(), family = B1_FONT,
            colour = "grey15") +
  annotate("text", x = 0.62, y = 1.0, hjust = 0, vjust = -0.55, label = "T = 1: no rescaling",
           size = b28_text_mm(), colour = "grey40", family = B1_FONT) +
  scale_x_discrete(labels = setNames(rs$axlab, as.character(rs$coh))) +
  scale_y_continuous(limits = c(0.8, 2.42)) +
  labs(title = "Every fitted out-of-cohort temperature exceeds 1, so each one softens",
       x = paste0("held-out cancer/study cohort\n",
                  "(hardest transfer first; ECE before recalibration below)"),
       y = "fitted temperature T") +
  theme_b1() + theme(panel.grid.major.x = element_blank(),
                     axis.text.x = element_text(size = B28_MIN_TEXT_PT))
b1_save(pT, "b28_F7_temperature", 9, 3.3, FIG)

# ---------------- TOC: single-panel ACS graphical abstract (≤ 3.25 in wide) ----------------
# Original identity/split-unit vector workflow, not the old six-point scatter.
# The dedicated renderer verifies current corrected table hashes, embeds Arial,
# and writes a native-text SVG plus an outlined display SVG for both sizes.
# The 3.25in x 1.70in TOC stays inside the achemso box. The separate 6.5in
# abstract adds pooled ranking, probability error, coverage and design boundaries;
# it is not silently substituted for a numbered scientific figure.
if (!NUMBERED_ONLY) {
  ga_renderer <- file.path(BASE, "scripts", "make_current_graphical_abstract.py")
  ga_python <- Sys.getenv("PYTHON", unset = "python3")
  ga_status <- system2(ga_python, args = c("-B", shQuote(ga_renderer)))
  if (ga_status != 0) stop("Current B28 graphical-abstract renderer failed", call. = FALSE)
}

cat("B28 figures done: F1 transfer, F2 ladder, F3 calibration, F4 risk-coverage,",
    "F5 protocol, F6 sensitivity, F7 temperature",
    if (NUMBERED_ONLY) "(GA/TOC excluded)\n" else ", TOC, full graphical abstract\n")
